using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry;

internal sealed class FiniteRelativeSimplicialCollapseDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Finite original-label relative simplicial collapses and cone extensions.",
        H("Finite collapse geometry"),
        Blocks(
            Paragraph(Text("A Sequence is an ordered finite list of actual free pairs. The realization composes their coordinate retractions, records every intermediate frame including the terminal n+1 frame, and fixes the entire final realization. Link, deletion, lifted-pair, and cone-extension APIs preserve original labels and distinguish combinatorial empty faces from geometric points.")),
            Node("sequence", "Sequence", "Finite sequence of exact free pairs",
                "Sequence K L is inductively generated by refl K and step P tail, where P is an actual CollapsePair whose retained complex is the ambient of tail. Its indices are exact PreAbstractSimplicialComplex V values, so every step stays on original labels.", DescribeRole.Definition),
            Node("sequence-pairs", "pairs", "Ordered pair list",
                "pairs S is [] for refl and P :: tail.pairs for step. The order is the construction order and is used by every pair-count and ordered-pair theorem.", DescribeRole.Definition),
            Node("sequence-monotone", "monotone", "Final complex is contained in each source",
                "For S : Sequence K L, L ≤ K. Each step composes tail.monotone with the retained inclusion.", DescribeRole.Theorem),
            Node("sequence-final-retained", "final_le_each_retained", "Final complex lies in each retained stage",
                "If P occurs in S.pairs, then L ≤ P.retained. This quantifies over the actual ordered list member.", DescribeRole.Theorem),
            Node("sequence-final-ambient", "final_le_each_ambient", "Final complex lies in each ambient stage",
                "If P occurs in S.pairs, then L ≤ P.ambient, by the retained inclusion.", DescribeRole.Theorem),
            Node("sequence-append", "append", "Concatenation",
                "append composes Sequence K L and Sequence L M into Sequence K M, preserving the left-to-right pair order.", DescribeRole.Definition),
            Node("sequence-cast", "cast", "Equality transport",
                "cast transports a sequence along definitional equalities of its source and target complexes and changes no original label, pair, or frame.", DescribeRole.Definition),
            Node("sequence-frames", "frames", "All intermediate complexes",
                "frames S is [K] for refl and P.ambient :: frames tail for step. It is the actual frame carrier list, one entry for each pair plus the terminal complex.", DescribeRole.Definition),
            Node("sequence-frames-refl", "frames_refl", "Reflexive frame list",
                "For refl K, the actual frame list is [K]. This is the zero-pair endpoint of the n+1 indexing convention.", DescribeRole.Theorem),
            Node("sequence-frames-step", "frames_step", "Step frame list",
                "For step P T, the actual frame list is P.ambient :: frames T, preserving construction order.", DescribeRole.Theorem),
            Node("sequence-frames-le-source", "frames_le_source", "Every frame is below the source",
                "Every M in frames S satisfies M ≤ K, preserving the original complex inclusion at every intermediate.", DescribeRole.Theorem),
            Node("sequence-frames-length", "frames_length", "n+1 frame count",
                "For every S, (frames S).length = S.pairs.length + 1. The terminal frame is included explicitly.", DescribeRole.Theorem),
            Node("sequence-getd", "getD_mem_of_lt", "In-range frame lookup",
                "If i < xs.length, xs.getD i d belongs to xs. This is the exact lookup lemma used to state frame identities over every i < pairs.length+1.", DescribeRole.Theorem),
            Node("sequence-pairs-cast", "pairs_cast", "Pair-list cast invariance",
                "Casting S along source and target equality leaves S.pairs definitionally unchanged.", DescribeRole.Theorem),
            Node("sequence-frames-cast", "frames_cast", "Frame-list cast invariance",
                "Casting S along source and target equality leaves frames S definitionally unchanged.", DescribeRole.Theorem),
            Node("sequence-pairs-append-length", "pairs_append_length", "Pair count under append",
                "For S : Sequence K L and T : Sequence L M, (S.append T).pairs.length = S.pairs.length + T.pairs.length.", DescribeRole.Theorem),
            Node("relative-sdr", "RelativeSDR", "Relative coordinate deformation package",
                "RelativeSDR K L h stores an actual retraction C(Space K,Space L), its equality on the literal realizationInclusion h, and a HomotopyRel from id to inclusion.comp retraction relative to every point in realization L. The fixed set is the entire final realization.", DescribeRole.Definition),
            Node("sequence-realize", "realize", "Composed relative deformation",
                "realize S composes elementary coordinate retractions in sequence order. The second homotopy segment is the tail homotopy evaluated after the first retraction, and the relative proof is on all of |L|, not just selected vertices.", DescribeRole.Definition),
            Node("sequence-inclusion", "inclusion", "Final coordinate inclusion",
                "inclusion S is realizationInclusion S.monotone from Space L into Space K.", DescribeRole.Definition),
            Node("sequence-retraction", "sequenceRetraction", "Composed retraction",
                "sequenceRetraction S is the retraction field of S.realize and remains in the original coordinate realization.", DescribeRole.Definition),
            Node("sequence-retraction-inclusion", "sequenceRetraction_inclusion", "Composed retraction fixes final points",
                "For y : Space L, sequenceRetraction S (inclusion S y) = y.", DescribeRole.Theorem),
            Node("sequence-homotopy", "collapseHomotopy", "Composed homotopy",
                "collapseHomotopy S is a HomotopyRel from id on Space K to inclusion S.comp sequenceRetraction S, relative to {x | x.val ∈ realization L}.", DescribeRole.Definition),
            Node("sequence-homotopy-fixed", "collapseHomotopy_fixed", "Whole final realization is fixed",
                "For all t : I, x : Space K, and hx : x.val ∈ realization L, collapseHomotopy S (t,x) = x. This is the exact relative fixed-set theorem.", DescribeRole.Theorem),
            Node("sequence-equivalence", "collapseEquiv", "Sequence homotopy equivalence",
                "collapseEquiv S is the actual homotopy equivalence Space K ≃ₕ Space L with the composed retraction and literal coordinate inclusion.", DescribeRole.Definition),
            Node("augmented-face", "AugmentedFace", "Empty-aware combinatorial face predicate",
                "AugmentedFace K s means s=∅ or s∈K. The empty branch is combinatorial only; realization still contains no point for the empty face.", DescribeRole.Definition),
            Node("augmented-downward", "augmented_downward", "Augmented downward closure",
                "If AugmentedFace K s, t⊆s, and t is empty or nonempty as appropriate, then AugmentedFace K t. The empty face is retained only in this predicate.", DescribeRole.Theorem),
            Node("augmented-retained", "augmented_retained", "Retained pair and augmented face",
                "For P and s, AugmentedFace P.retained s iff AugmentedFace P.ambient s and P.lower is not a subset of s. This is the empty-aware analogue of retained membership.", DescribeRole.Theorem),
            Node("fresh", "Fresh", "Fresh vertex predicate",
                "Fresh v K means v is absent from every face of K. This is a face-level condition, so ghost labels are not materialized as singleton faces.", DescribeRole.Definition),
            Node("deletion", "deletion", "Whole original deletion",
                "deletion K v keeps exactly the original nonempty faces s∈K with v∉s.", DescribeRole.Definition),
            Node("link", "link", "Original-label link",
                "link K v has nonempty faces s with v∉s and insert v s∈K, all on the original V type.", DescribeRole.Definition),
            Node("deletion-le", "deletion_le", "Deletion inclusion",
                "deletion K v ≤ K.", DescribeRole.Theorem),
            Node("deletion-fresh", "deletion_fresh", "Deleted vertex is fresh",
                "Fresh v (deletion K v).", DescribeRole.Theorem),
            Node("link-le-deletion", "link_le_deletion", "Link lies in deletion",
                "link K v ≤ deletion K v.", DescribeRole.Theorem),
            Node("cone", "cone", "Finite cone complex",
                "cone v L contains the original faces of L and the faces insert v s for s∈L, retaining original labels and allowing L to have no faces.", DescribeRole.Definition),
            Node("apex-mem-cone", "apex_mem_cone", "The original apex singleton is a cone face",
                "For every original label v and native complex L, the nonempty singleton {v} belongs to cone v L, including when L is bottom. This is face membership, not an assumed geometric point or contraction.", DescribeRole.Theorem),
            Node("cone-face", "cone_face", "Cone closure",
                "Every face of cone v L remains a face after adjoining v.", DescribeRole.Theorem),
            Node("base-le-cone", "base_le_cone", "Base inclusion in cone",
                "L ≤ cone v L.", DescribeRole.Theorem),
            Node("cone-mono", "cone_mono", "Cone monotonicity",
                "L≤M implies cone v L≤cone v M.", DescribeRole.Theorem),
            Node("link-union-cone", "link_union_cone", "Link of a union with a fresh cone",
                "Under M≤D and Fresh v D, link (D ⊔ cone v M) v = M.", DescribeRole.Theorem),
            Node("deletion-union-cone", "deletion_union_cone", "Deletion of a union with a fresh cone",
                "Under M≤D and Fresh v D, deletion (D ⊔ cone v M) v = D.", DescribeRole.Theorem),
            Node("deletion-union-link-cone", "deletion_union_link_cone", "Whole complex decomposes at an actual vertex",
                "If {v}∈K, deletion K v ⊔ cone v (link K v) = K. The singleton hypothesis prevents ghost vertices from being introduced.", DescribeRole.Theorem),
            Node("pair-lift-over", "liftPairOver", "Lift a free pair over a fixed deletion",
                "Pair.liftPairOver P D v hPD hvD has ambient D ⊔ cone v P.ambient, lower insert v P.lower, the same apex P.apex, and exact free-pair proof. It stays on original labels.", DescribeRole.Definition),
            Node("pair-lift-retained", "liftOver_retained", "Lifted retained complex",
                "The retained complex of Pair.liftPairOver is D ⊔ cone v P.retained.", DescribeRole.Theorem),
            Node("pair-le-lift-retained", "le_liftOver_retained", "Deletion survives a lifted pair",
                "D ≤ (Pair.liftPairOver P D v hPD hvD).retained.", DescribeRole.Theorem),
            Node("pair-link-lift-retained", "link_liftOver_retained", "Lifted link recovers retained source",
                "link (Pair.liftPairOver P D v hPD hvD).retained v = P.retained.", DescribeRole.Theorem),
            Node("sequence-lift-over", "liftOver", "Lift an ordered sequence",
                "liftOver S D v hMD hvD adjoins v to every lower face and to every intermediate frame, yielding Sequence (D ⊔ cone v M) (D ⊔ cone v N).", DescribeRole.Definition),
            Node("pairs-lift-length", "pairs_liftOver_length", "Lift preserves pair count",
                "The lifted sequence has exactly S.pairs.length pairs.", DescribeRole.Theorem),
            Node("pairs-lift-forall", "pairs_liftOver_forall2", "Lifted ordered-pair correspondence",
                "List.Forall₂ relates each output pair, in output order, to the source pair by the exact Pair.liftPairOver constructor and its ambient/fresh witnesses.", DescribeRole.Theorem),
            Node("frames-lift", "frames_liftOver", "Lifted frame list",
                "frames (S.liftOver D v hMD hvD) = (frames S).map (fun L => D ⊔ cone v L).", DescribeRole.Theorem),
            Node("list-getd-map", "list_getD_map", "Mapped frame lookup",
                "getD commutes with the map used by lifted frames, with the same default image.", DescribeRole.Theorem),
            Node("frames-lift-getd", "frames_liftOver_getD", "Exact lifted frame at every index",
                "For every i, the lifted frame getD equals D ⊔ cone v (S.frames.getD i M), preserving the n+1 frame indexing.", DescribeRole.Theorem),
            Node("frames-append-getd", "frames_append_getD_lt", "Prefix frames under append",
                "For i < S.pairs.length+1, frames (S.append T).getD i K = frames S.getD i K.", DescribeRole.Theorem),
            Node("terminal-pair", "terminalPair", "Terminal singleton free pair",
                "Given Fresh v D, v≠w, and {w}∈D, terminalPair D v w has ambient D ⊔ cone v (vertexComplex w), lower {v}, apex w, and exact freeness.", DescribeRole.Definition),
            Node("terminal-pair-retained", "terminalPair_retained", "Terminal pair retains D",
                "The retained complex of terminalPair D v w is exactly D.", DescribeRole.Theorem),
            Node("link-collapse-deletion", "linkCollapseDeletion", "Link sequence collapses to whole deletion",
                "Given S : Sequence (link K v) (vertexComplex w), linkCollapseDeletion lifts S over deletion K v, appends the actual terminal pair, and casts through deletion_union_link_cone to produce Sequence K (deletion K v).", DescribeRole.Definition),
            Node("link-deletion-sdr", "linkDeletionSDR", "Relative link-to-deletion SDR",
                "linkDeletionSDR is the RelativeSDR obtained from linkCollapseDeletion. Its inclusion is the actual coordinate inclusion and its homotopy fixes the entire deletion realization, including disconnected components and ghost labels.", DescribeRole.Definition),
            Node("lower-not-subset-cone", "lower_not_subset_cone", "No new coface inside retained cone",
                "If L≤P.retained, v is fresh in P.ambient, and s∈cone v L, then P.lower is not a subset of s. This is the obstruction used to preserve the same free pair.", DescribeRole.Theorem),
            Node("extend-cone", "extendCone", "Extend a free pair across a retained cone",
                "Pair.extendCone preserves P.lower and P.apex, adds cone v L to the ambient, and proves freeness from lower_not_subset_cone.", DescribeRole.Definition),
            Node("extend-cone-retained", "extendCone_retained", "Extended retained complex",
                "The retained complex of Pair.extendCone P L v is P.retained ⊔ cone v L.", DescribeRole.Theorem),
            Node("extend-across-cone", "extendAcrossCone", "Extend a sequence across a cone",
                "extendAcrossCone S v hv yields Sequence (K ⊔ cone v L) (cone v L), preserving every original pair and adjoining the entire cone to the final complex.", DescribeRole.Definition),
            Node("cone-extension-sdr", "coneExtensionSDR", "Relative SDR onto the full cone",
                "coneExtensionSDR is the realized extension and fixes every point of the entire cone realization throughout the first collapse segment.", DescribeRole.Definition),
            Node("self-cone-pair", "selfConePair", "Actual cone owner adapter",
                "selfConePair v L supplies ConePair for cone v L using the existing cone apex face and cone closure.", DescribeRole.Definition),
            Node("cone-point", "conePoint", "Actual apex coordinate point",
                "conePoint v L is the existing ConePair.apexPoint in Space (cone v L).", DescribeRole.Definition),
            Node("cone-contraction", "coneContraction", "Contraction to the actual apex",
                "coneContraction is the straight homotopy in the original coordinate realization from the identity to the constant conePoint, relative to the singleton apex. The segment proof is reused from the existing FiniteConeCollapse owner.", DescribeRole.Definition),
            Node("cone-extension-contraction", "coneExtensionContraction", "Two-stage contraction of the original union",
                "The first segment realizes extendAcrossCone and fixes the full cone; the second applies coneContraction through the composed retraction. The resulting HomotopyRel is relative to the singleton containing the actual included apex, so both segments fix that point. It contracts Space (K ⊔ cone v L) to the actual apex without a null-map or abstract contractibility premise.", DescribeRole.Definition),
            Node("pairs-append", "pairs_append", "Exact concatenation of ordered pairs",
                "For S:Sequence K L and T:Sequence L M, (S.append T).pairs = S.pairs ++ T.pairs. This records terminal append without changing pair order.", DescribeRole.Theorem),
            Node("frames-source-zero", "frames_source_zero", "Actual initial frame",
                "For S:Sequence K L and any fallback complex D, S.frames.getD 0 D = K. The append-prefix proof uses the actual source frame, including when S has no pairs.", DescribeRole.Theorem)
            )));

    private const string Prefix = "D5/S3/Geometry/FiniteRelativeSimplicialCollapse.";

    private static DocumentBlock Node(string id, string declaration, string heading, string prose,
        DescribeRole role) => Describe.Lean(
        DescribeId.Create(id),
        DeclarationHandle.Create(Prefix + declaration), H(heading),
        StatementSource.FromLean(), AssessedProvenance.FromRepo(),
        Blocks(Paragraph(Text(prose))), role);
}
